}

export interface SaveServiceQualityRulePayload {
  rule_name: string;
  rule_type: string;
  description?: string;
  deduct_score: number;
  pass_threshold: number;
  trigger_keywords?: string[];
  response_timeout_sec?: number;
  enabled?: number;
  sort?: number;
  platform_id?: string;
  dept_id?: string;
  shop_id?: string;
}

export interface SaveServiceSensitiveTermPayload {
  term: string;
  category: string;
  severity?: number;
  enabled?: number;
  replace_text?: string;
  description?: string;
  platform_id?: string;
  dept_id?: string;
